/** A reason in the person's language, inside a message or on its own. */
fun Cause.text(context: Context): String =
    when (this) {
        is Cause.NoSources -> Strings.causeNoSources(context)
        is Cause.NoConnection -> Strings.causeNoConnection(context)
        is Cause.AirsToday -> Strings.causeAirsToday(context, this.time)
        is Cause.AirsTomorrow -> Strings.causeAirsTomorrow(context, this.time)
        is Cause.AirsInDays -> Strings.causeAirsInDays(context, this.days.toInt(), this.time)
        is Cause.AirsOnDate -> Strings.causeAirsOnDate(context, this.date, this.time)
        is Cause.NoPlayableStream -> Strings.causeNoPlayableStream(context)
        is Cause.TitleNoMatch -> Strings.causeTitleNoMatch(context, this.detail)
        is Cause.SourceGone -> Strings.causeSourceGone(context, this.source)
        is Cause.ReleaseFailed -> Strings.causeReleaseFailed(context, this.detail)
        is Cause.SourcesTimedOut -> Strings.causeSourcesTimedOut(context)
        is Cause.NoSourceHasEpisode -> Strings.causeNoSourceHasEpisode(context, this.episode, this.detail)
        is Cause.SourceCannotDownload -> Strings.causeSourceCannotDownload(context)
        is Cause.NoSourceCouldListShow -> Strings.causeNoSourceCouldListShow(context)
        is Cause.SubtitlesMerged -> Strings.causeSubtitlesMerged(context, this.tracks.toInt())
        is Cause.SubtitlesLeftApart -> Strings.causeSubtitlesLeftApart(context, this.reason)
        is Cause.AlreadyInDownloads -> Strings.causeAlreadyInDownloads(context, this.count.toInt())
        is Cause.ProxyNeedsAddress -> Strings.causeProxyNeedsAddress(context)
        is Cause.ProxyAddressUnusable -> Strings.causeProxyAddressUnusable(context)
        is Cause.ServerUnreachable -> Strings.causeServerUnreachable(context)
        is Cause.Verbatim -> this.text
    }

/** A wait or a countdown in the catalogue's units: "2d 4h", "12m", "40s". */
fun spanText(context: Context, s: Span): String {
    val days = s.days.toInt()
    val hours = s.hours.toInt()
    val minutes = s.minutes.toInt()
    val seconds = s.seconds.toInt()
    return when {
        days > 0 -> if (hours > 0) Strings.durationDaysHours(context, days, hours) else Strings.durationDays(context, days)
        hours > 0 -> if (minutes > 0) Strings.durationHoursMinutes(context, hours, minutes) else Strings.durationHours(context, hours)
        minutes > 0 ->
            if (seconds > 0) Strings.durationMinutesSeconds(context, minutes, "%02d".format(seconds))
            else Strings.durationMinutes(context, minutes)
        seconds > 0 -> Strings.durationSeconds(context, seconds)
        else -> Strings.durationMinutes(context, 0)
    }
}

/** A size at human scale in the person's number format: "9.4 MB". */
fun sizeText(context: Context, s: Size): String {
    val number = NumberFormat.getInstance().apply {
        minimumFractionDigits = s.decimals.toInt()
        maximumFractionDigits = s.decimals.toInt()
    }.format(s.value)
    return when (s.unit) {
        SizeUnit.BYTE -> Strings.sizeByte(context, number)
        SizeUnit.KILOBYTE -> Strings.sizeKilobyte(context, number)
        SizeUnit.MEGABYTE -> Strings.sizeMegabyte(context, number)
        SizeUnit.GIGABYTE -> Strings.sizeGigabyte(context, number)
    }
}

/** A whole percentage in the person's format, with no space in English: "82%". */
fun percentText(percent: Int): String = NumberFormat.getPercentInstance().format(percent / 100.0)
